(()=>{if(window.__SV_ACTION_BRIDGE__)return;window.__SV_ACTION_BRIDGE__=true;const $=s=>document.querySelector(s);const modal=$('#actionModal'),box=$('#modalContent');function open(html){if(!modal||!box)return;box.innerHTML=html;modal.classList.add('show');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}function close(){if(!modal)return;modal.classList.remove('show');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}function toast(m){const t=$('#toast'),s=t?.querySelector('span');if(s)s.textContent=m;if(t){t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}}function fallback(a){const labels={login:['MASUK WARGA','Buka aplikasi SIM RT/RW untuk layanan personal.'],news:['NEWS ENGINE','Berita dan informasi publik.'],article:['ARTIKEL','Konten editorial lengkap.'],gis:['GIS DESA','Peta publik dengan batas data aman.'],privacy:['PRINSIP DATA','Transparansi sumber, klasifikasi, dan penggunaan data.']};if(a==='area'){open('<span class="eyebrow dark">WILAYAH</span><h2 class="modal-title">Pilih wilayah RT/RW</h2><p class="modal-copy">Pilihan wilayah akan digunakan sebagai konteks tampilan publik.</p><div class="modal-cta"><button class="btn btn-outline-civic" data-close-modal>Tutup</button></div>');return}if(a==='services'||a==='population'||a==='complaint'||a==='letter'||a==='activities'||a==='tracking'||a==='public-data'){open('<span class="eyebrow dark">LAYANAN PUBLIK</span><h2 class="modal-title">Smart Village / Desa Cerdas</h2><p class="modal-copy">Modul layanan sedang dipulihkan. Silakan muat ulang halaman sekali; sesi dan data tidak berubah.</p><div class="modal-cta"><button class="btn btn-civic" data-home>Home</button><button class="btn btn-outline-civic" data-close-modal>Tutup</button></div>');return}const p=labels[a];if(p)open('<span class="eyebrow dark">SMART VILLAGE</span><h2 class="modal-title">'+p[0]+'</h2><p class="modal-copy">'+p[1]+'</p><div class="modal-cta"><button class="btn btn-outline-civic" data-home>Home</button><button class="btn btn-outline-civic" data-close-modal>Tutup</button></div>')}document.addEventListener('click',e=>{const closeBtn=e.target.closest('[data-close-modal]');if(closeBtn){e.preventDefault();close();return}const home=e.target.closest('[data-home]');if(home){e.preventDefault();close();window.scrollTo({top:0,behavior:'smooth'});return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const sv=window.smartVillage;try{if(sv){if(action==='area'&&sv.applyArea){sv.applyArea(action);return}if(sv.serviceModal&&(action==='services'||['population','complaint','letter','activities','tracking','public-data'].includes(action))){sv.serviceModal(action==='services'?undefined:action);return}if(sv.openModal&&action==='chat'){sv.openModal('<span class="eyebrow dark">RUANG WARGA</span><h2 class="modal-title">Ruang Warga</h2><p class="modal-copy">Pilih layanan komunikasi warga.</p>');return}if(sv.openModal&&action){sv.openModal('<span class="eyebrow dark">SMART VILLAGE</span><h2 class="modal-title">'+action+'</h2>');return}}fallback(action)}catch(err){console.error('Smart Village action bridge:',err);fallback(action)}} ,true)})();